-- 테이블 mydata.checklist_result 구조 내보내기
CREATE TABLE IF NOT EXISTS `checklist_result` (
  `result_id` int(11) NOT NULL AUTO_INCREMENT,
  `진단지역` varchar(100) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `ID` varchar(50) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `district_code` varchar(50) DEFAULT NULL,
  `위도` decimal(10,8) DEFAULT NULL,
  `경도` decimal(11,8) DEFAULT NULL,
  `대분류` varchar(50) DEFAULT NULL,
  `중분류` varchar(50) DEFAULT NULL,
  `질문기준` varchar(255) DEFAULT NULL,
  `answers` varchar(4000) DEFAULT NULL,
  `점수` int(11) DEFAULT NULL,
  `리뷰` varchar(1000) DEFAULT NULL,
  `만족도` varchar(50) DEFAULT NULL,
  `이미지경로` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`result_id`),
  KEY `user_id` (`user_id`),
  KEY `ix_checklist_result_result_id` (`result_id`),
  CONSTRAINT `1` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

